@Serializable(with = PlanView.Serializer::class)
data class PlanView(
    val status: PlanStatus,
    val reasons: List<CopyLine>,
    val prompts: List<PromptView>,
    val meta: PlanMeta,
    val summary: SummaryView?,
    val days: List<DayView>,
    val blocks: List<BlockView>,
    val warnings: List<NoteView>,
) {
    object Serializer : KSerializer<PlanView> {
        override val descriptor: SerialDescriptor =
            SerialDescriptor("net.chronoflow.core.model.contracts.PlanView", PlanViewWire.serializer().descriptor)

        override fun deserialize(decoder: Decoder): PlanView {
            val wire = decoder.decodeSerializableValue(PlanViewWire.serializer())
            return PlanView(
                status = wire.status,
                reasons = wire.reasons,
                prompts = wire.prompts.filter { ProfilePreferences.isSupported(it) },
                meta = wire.meta,
                summary = wire.summary,
                days = wire.days,
                blocks = wire.blocks,
                warnings = wire.warnings,
            )
        }

        override fun serialize(encoder: Encoder, value: PlanView) {
            val wire = PlanViewWire(
                status = value.status,
                reasons = value.reasons,
                prompts = value.prompts,
                meta = value.meta,
                summary = value.summary,
                days = value.days,
                blocks = value.blocks,
                warnings = value.warnings,
            )
            encoder.encodeSerializableValue(PlanViewWire.serializer(), wire)
        }

        private fun json(coder: Any): Json =
            when (coder) {
                is JsonDecoder -> coder.json
                is JsonEncoder -> coder.json
                else -> throw SerializationException("PlanView supports JSON only")
            }
    }
}

